COLLDATA("sh11237","ar",[[1,"وسمعته يقول: هشيم عن إسماعيل بن سالم كوفي ثقة. أيوب"],[2,"سمعته يقول: أيوب بن ياسر مديني كان بفيد، متروك روى عن سهيل وسمى وهشام٣."],[3,"وأيوب بن عتبة عن يحي بن أبي كثير هو يمامي يترك. وقال مرة أخرى يعتبر به شيخ٤ قيل له."],[4,"مثل أيوب بن جابر٥ قال: لا. هذا قوي، يعني أيوب بن عتبة أقوى."],[5,"أيوب بن هانئ عن أبيه. هو كوفي يعتبر به، وسمعته يقول مرة أخرى ابن هانئ الذي حدث عنه ابن جريج يعتبر به١."],[6,"وأيوب بن واقد عن أبي ليلى بصري متروك٢."],[7,"وأيوب أبو العلاء القصاب هو ابن أبي مسكين وقيل ابن مسكين شيخ من أهل واسط يعتبر به."],[8,"وأيوب بن وايل يحدث عن نافع حدث عنه حماد بن زيد وهو مقل من أهل البصرة، صاحب حديث لا بأس به٣. إبراهيم"],[9,"سمعته يقول إبراهيم بن إسحاق الصيني متروك٤."],[10,"وإبراهيم بن هراسه متروك لا يخرج حديث٥."],[11,"وإبراهيم بن إسماعيل بن مجمع متروك."],[12,"وإبراهيم بن إسماعيل بن أبي حبيبة متروك."],[13,"وإبراهيم بن بكر الشيباني بغدادي متروك."],[14,"وإبراهيم بن نافع من أهل مكة لا بأس به."],[15,"وإبراهيم بن نشيط٦ الوعلاني يحدث عنه ابن وهب مدني يقة. إسحاق"],[16,"وسمعته يقول إسحاق بن أبي إسحاق الشيباني يحدث عن أبيه ثقة كوفي."],[17,"وإسحاق بن زيد الهذلي يحدث عنه ابن أبي ذئب مديني لا بأس به."],[18,"وإسحاق بن عمر عن عائشة، مجهول يترك١."],[19,"وإسحاق بن إبراهيم أبو النضر الدمشقي ثقة يحدث عنه فهد بن سليمان، قال البرقاني رحمه الله، الذي في التعليق عندنا بن زيد أبو النضر الدمشقي٢. أحمد"],[20,"سمعته يقول أحمد بن خالد الوهبي لا بأس به."],[21,"وأحمد بن عبد الوهاب بن نجدة حمصي يحدث عن أبيه لا بأس بهما."],[22,"وأحمد بن عبد الله الفربناني٣ مروزي متروك."],[23,"وأحمد بن عبد الله الجويباري هروي متروك. وسمعته يقول:"],[24,"أحوص بن حكيم بن عمير العنسي حمصي يعتبر به إذا حدث عنه ثقة١."],[25,"أيمن بن عبيد بن أم أيمن أخو أسامة بن زيد لأمه قتل في عهد النبي صلى الله عليه وسلم."],[26,"وأصبغ بن زيد الوراق واسطي ثقة عندي يروي عن ثور بن زيد وقد تكلم فيه٢."],[27,"وأسيد بن أبي أسيد٣ البراد مدني يعتبر به."],[28,"إياس بن صبيح هو أبو مريم الجعني بصري تابعي ثقة٤."],[29,"وأشعث بن بنت دجاجة، قال من أهل الكوفة صالح ويقال له فليت."],[30,"وسمعته يقول: عطاء عن أيمن ليس بصحابي هو والد عبد الواحد، عن النبي صلى الله عليه وسلم مرسل."],[31,"وسمعته يقول: أسد بن عمرو البجلي يعتبر به."],[32,"وقلت له: أشعث عن الحسن، فقال: هم ثلاثة يحدثون جميعا عن الحسن أحدهم الحمراني المنسوب إلى حمران مولى عثمان، بصري وهو أشعث بن عبد الملك أبو هاني ثقة."],[33,"وأشعث بن عبد الله الحداني بصري أيضا يروي عن أنس والحسن يعتبر به."],[34,"وأشعث بن سوار الكوفي يعتبر به وهو أضعفهم روى عنه شعبة حديثا واحدا. في حرف الباء"],[35,"قلت لأبي الحسن روى حرب بن شداد عن يحي بن أبي كثير عن باب عن ابن عمير عن رجل عن أبيه عن أبي هريرة؟. قال.... باب لا أدري من هو يحدث عنه الأوزاعي ويحي ويترك هذا الحديث١."],[36,"وسمعته يقول: بدر بن عثمان كوفي ثقة."],[37,"وبدر بن خليل الأسدي كوفي روى عنه شريك لا بأس به."],[38,"وسمعته يقول: بركة بن يعلى عن أبي سويد العبدي عن ابن عمر مجهولان٢."],[39,"وسمعته يقول بسطام بن عبد الوهاب عن مكحول مجهول٣."],[40,"سألته عن بشر بن عمارة الخثعمي فقال: متروك."],[41,"وعن بشر بن السري، فقال: ثقة مكي٤."],[42,"وسألته عن بشير بن ميمون عن مجاهد فقال: أو صيفي واسطي متروك."],[43,"وسألته عن بشير بن سليمان فقال: أبو إسماعيل كوفي لا بأس به."],[44,"قلت له: روى بركة عن بشير بن نهيك، فقال بركة شيخ للبصريين يعتبر به."],[45,"وبشير بصري ثقة."],[46,"وسمعته يقول: بكر بن عبد الرحمن بن عبد الله بن عيسى بن عبد الرحمن ابن أبي ليلبى: قاضي الكوفة ثقة١."],[47,"وبكر بن عمرو المعافا٢ بصري يعتبر به."],[48,"وبكر بن خنيس: متروك كان ببغداد٣."],[49,"وبكر بن وايل بن داود كوفي ثقة ثقة، يروي أبوه عنه."],[50,"وسمعته يقول: معتمر عن بيان أبي سهيل الرقاشي عن أنس، يقول البخاري هو الذي يحدث عنه شعبة ويكنيه أبا صدقة، وقال غيره صاحب شعبة اسمه سليمان بن كندير أبو صدقة٤."],[51,"سألته عن زريع بن حسان، فقال: أبو الخليل بصري متروك. قلت له: عن هشام بن عروة عجايب، قال هي بواطيل، ثم قال كل شيء له باطل. في حرف التاء والثاء سمعت أبا الحسن الدارقطني رحمه الله يقول:"],[52,"تميمة بنت سلمة عن عائشة لا بأس بها."],[53,"ثابت بن عمارة بصري ثقة."],[54,"ثابت بن أبي صفية أبو حمزة الثمالي١ متروك."],[55,"ثمامة بن شراحبيل عن ابن عمر من أهل صنعاء لا بأس به٢ شيخ مقل."],[56,"ثوير بن أبي فاختة مولى بني هاشم متروك، وأبو فاختة سعيد ابن علاقة٣. في حرف الجيم سألت أبا الحسن علي بن عمر عن:"],[57,"الجراح أبي وكيع، فقال ليس بشيء هو كثير الوهم، قلت يعتبر به، قال: لا."],[58,"وسألته عن الجلاح أبي كثير فقال لا بأس به مصري٤."],[59,"وسألته عن جسرة بنت دجاجة، فقال: يعتبر بحديثها إلا أن بحدث عنها من يترك."],[60,"وسألته عن جسر بن فرقد فقال متروك."],[61,"وسألته عن جبارة بن مغلس فقال متروك."],[62,"قلت له، جميل بن حماد عن عصمة بن زامل عن أبيه عن أبي هريرة ... فقال هذا إسناد بدوي يخرج اعتبارا٥."],[63,"قلت فجميل بن عبيد الطائي، قال هو بصري يعتبر به."],[64,"سألته عن الجارود بن أبي سبرة١ والد ربعي فقال بصري ثقة."],[65,"وسألته عن جعفر بن برد٢ عن مولاته أم سالم الدوسية عن عائشة فقال يترك الحديث، وليس يروي عن أم سالم غير جعفر هذا وهو شيخ بصري مقل يعتبر به."],[66,"قلنا له جعفر بن عمران يحدث عنه أحمد بن يونس فقال لا أعرفه."],[67,"قلت: جعفر بن أحمد بن عمران يحدث عنه الطلحي، فقال كوفي ثقة حدث عنه الناس قديما."],[68,"قلت: جعفر بن ميمون فقال بصري يحدث عنه الثوري وغيره يعتبر به."],[69,"قلت له: فجعفر بن زياد الأحمر. فقال كوفي يعتبر به."],[70,"قلت جعفر بنأبي الحسن الخواري٣ يحدث عن غنام٤ عنه قال متروك."],[71,"قلت له: وأبو الحسن بن المظفر حاضر، جعفر بن برقان، فقالا جميعا، قال أحمد بن حنبل يؤخذ من حديثه ما كان عن غير الزهري فأما عنه فلا، قلت فقد لقيه فما بلاؤه، قال الدراقطني: ربما حدث عن الثقة عن ابن برقان عن الزهري ويحدثه الآخر عن ابن برقان عن رجل عن الزهري أويقول بلغني عن الزهري فأما حديثه عن ميمون ابن مهران ويزيد بن الأصم فثابت صحيح١. في حرف الحاء قلت لأبي الحسن:"],[72,"أبو المليح الرقى الحسن بن عمر، فقال ابن عمر وقيل ابن عمرو والأول هو الصواب ثقة."],[73,"وسألته عن الحسن بن يزيد الأصم صاحب السدي. قال كوفي لا بأس به. ثقة مستقيم الحديث٢."],[74,"قلت له الحسن بن شبيب المؤدب. فقال أخباري يعتبر به وليس بالقوي يحدث عنه المحاملي٣."],[75,"قلت له: الحسين بن زيد بن علي بن الحسين٤ عن عبد الله بن محمد ابن عمر بن علي عن أبيه عن جده عن علي. فقال كلهم ثقات."],[76,"قلت له. الحسين بن محمد بن شنبه٥ يحدث عنه المقانعي والقتات، فقال واسطي صالح."],[77,"سألته عن الحسين بن عبد الله بن ضميره فقال متروك٦ لا يحدث إلا عن أبيه عن جده."],[78,"وعن الحسن بن زياد اللؤلؤي فقال كوفي متروك١."],[79,"سألته عن حبيب بن أبي مرزوق يحدث عنه جعفر بن برقان فقال هو جزري ثقة يحتج به."],[80,"قلت له حبيب عن أنس: فقال هذا حبيب الإسكاف أبو عميرة كوفي متروك٢."],[81,"قلت له حبيب بن أبي حبيب يروي عن عبد الرحمن بن القاسم فقال شيخ بصري يعتبر به٣."],[82,"قلت حميد بن حماد بن خوار، فقال وقيل ابن أبي الخوار٤ من أهل الموفة يعتبر به."],[83,"قلت حميد بن صخر أبو صخر. فقال هو حميد بن زياد مدني، ولكن كذا يقال. وهو ثقة."],[84,"قلت فحميد بن علي العقيلي فقال لا يستقيم حديثه. لا يحتج به."],[85,"قلت فحميد بن هانئ أبو هاني قال مصري لا بأس به. ثم قال ثقة."],[86,"قلت فحميد مولى٥ علقمة عن عطاء. قال مجهول."],[87,"قلت حميد بن عطاء. عن عبد الله بن الحارث ابن مسعود، فقال: حميد متروك، أحاديثه شبه الموضوعة وهو كوفي، وعبد الله بن الحارث كوفي ثقة ولم يسمع من ابن مسعود١."],[88,"وسألته عن الحكم بن عبد الله الأيلي٢ صاحب القاسم بن محمد فقال متروك."],[89,"وسمعته يقول الحكم بن مينا٣ من أهل المدينة ثقة."],[90,"وسألته عن حكيم بن جبير فقال كوفي يترك، هو الذي روى \"لا تحل الصدقة لمن له خمسون درهما\" ٤."],[91,"قلت له: الحارث بن حجاج عم أبي الحجاج عن أبي معمر عن سالم ابن عبد الله، فقال مجهولان."],[92,"قلت: معن عن الحارث بن عبد الله الليثي فقال مدني صالح."],[93,"قلت الحارث بن عمران، قال: أبو سهل الجعفري كوفي متروك."],[94,"وسمعته يقول: الحارث بن حصيرة٥ شيخ للشيعة يغلو في التشيع."],[95,"وسمعته يقول الحارث بن عمير أبو عمير، بصري سكن مكة، وهو ثقة٦."],[96,"وسمعته يقول حجاج بن أبي عثمان الصواف، يكنى أبا الصلت بصري ثقة يروي عن أبي الزبير ويحي بن ابي كثير."],[97,"وحجاج بن أبي زينب يكنى أبا يوسف واسطي يروي عن أبي عثمان وعن أبي سفيان طلحة بن نافع، يروي عنه الواسطيون، ثقة١"],[98,"وحجاج بن أرطأة أبو أرطأه كوفي."],[99,"وسألته عن حرب بن سريج٢ يحدث عنه طالوت بن عباد، فقال.. المقري. بصري صالح. وأخوه بشر بن سريج صالح."],[100,"سالته عن حيان بن علي وأخيه مندل، فقال متروكان، وقال مرة أخرى ضعيفان٣ ويخرج حديثهما٤."],[101,"وسمعته يقول الحريش بن الخريت٥ أخو الزبير بن الخريت يعتبر به وهما بصريان والزبير ثقة."],[102,"قلت له حابس اليماني عن أبي بكر الصديق، فقال مجهول متروك٦ قلت له عن أبي ذر، فقال لايثبت مصري يترك."],[103,"قلت له: أبو شهاب عن حمزة فقال هو حمزة النصيبي يحدث عن عمرو وغيره متروك."],[104,"قلت له: أبو العلاء بن الشخير عن الحنظلي عن شداد، فقال أبو العلاء اسمه يزيد أخو مطرف، والحنظلي مجهول لا يسمى، يترك هذا الحديث."],[105,"وسمعته يقول: أبو غالب اسمه حزور١ بصري لا يعتبر به٢ وقلت له مرة أخرى أبو غالب عن أبي أمامة فقال بصري واسمه حزور، قلت ثقة قال نعم."],[106,"وسمعته يقول حزم بن أبي حزم القطعي ثقة."],[107,"قلت له حصن٣ عن أبي سلمة بن عبد الرحمن فقال يحدث عنه الأوزاعي يعتبر به٤."],[108,"قلت: فحصين بن نافع المازني، فقال بصري روى عن الحسن حديثين أو ثلاثة ليس به بأس."],[109,"سألته عن حصين بن جندب أبي ظبيان فقال: ثقة."],[110,"سألته عن حفص بن عمر القناد٥ فقال: هو من ناحية العسكر متروك، يحدث عته عبد الله بن رشيد وهو يحدث عن عبد الله بن عمر."],[111,"سألته عن حفص بن عمر الحلبي، فقال اجعله كوفي، ثم ولي قضاء حلب، صالح يعتبر به١."],[112,"وعن الحسام بن مصك٢ فقال بصري يعتبر به."],[113,"سألته عن حفصة بنت عازب فقال: هي بنت عبيد بن عازب عن البراء لا يكاد يحدث عنها غير ابن أبي ليلى يخرج حديثها."],[114,"قلت له: حفص عن أنس هو ابن أخي أنس، قال نعم، هو حفص ابن عمر بن عبد الله بن أبي طلحة، قلت ثقة قال نعم. في حرف الخاء"],[115,"سمعته يقول: خصيف٣ بن عبد الرحمن جزري يعتبر به. يهم."],[116,"وسمعته يقول: خازم بن الحسين أبو إسحاق الحميس٤ بصري وقع إلى الكوفة في آخر أمره، متروك يحدث عن مالك بن دينار وغيره."],[117,"قلت له أحمد بن يونس عن الخزرج٥ بن عثمان عن أبي أيوب عن أبي هريرة....جماعة ولكن هذا مجهول."],[118,"قلت له: خليد بن دعلج، ثقة قال: لا."],[119,"قلت: عطاء الخرساني عن خليد السلامي١ عن أم الدرداء فقال: مجهول ثقة٢."],[120,"قلت: خلف بن عقبة عن أبي الزهراء خادم أنس بن مالك فقال: خلف بصري وأبو الزهراء مجهول."],[121,"سألته عن خلف بن محمد بن عيسى، فقال: أبو الحسين يعرف بكردوس٣ واسطي ثقة."],[122,"سألته عن خالد بن حسان يروي عنه ابن نمير فقال: هو أبو يزيد الخراز لا بأس به."],[123,"وسألته عن خالد بن مشكان، الفراء فقال: البصري مقل يعتبر به."],[124,"وسألته عن خالد بن يزيد بن صالح بن صبيح المري، فقال: والد عراك، هو دمشقي يعتبر به."],[125,"وعن الخصيب بن زيد يروي عن الحسن فقال: شيخ لا بأس به، ليس له كبير مسند. في حرف الدال"],[126,"سمعته يقول: داود بن بكر بن أبي الفرات ويقال داود بن أبي الفرات مدني يعتبر به."],[127,"وداود بن عطاء من أهل مكة١ متروك."],[128,"وداود الطفاوي بصري يترك."],[129,".وداود الطائي هو ابن نصير٢"],[130,"وداود بن أبي عاصم بن مسعود القفي طايفي محتج به."],[131,"وسمعته يقول دراج٣ أبو السمح هو ابن سمعان مصري متروك."],[132,"قلت له: أبو سعيد عن علي قال: هو عقيصا واسمه دينار متروك."],[133,"وسألته عن داهر بن نوح، فقال لا بأس به٤."],[134,"وعن دلهم بن صالح، فقال: كان بالكوفة صالح. في حرف الذال"],[135,"سألته عن ذي مخبر٥ صاحب النبي صلى الله عليه وسلم فقال: هو ابن أخي النجاشي. في حرف الراء"],[136,"سمعته يقول: روح بن غطيف متروك."],[137,"ورفدة٦ بن قضاعة متروك."],[138,"وأبو عصام رواد١ بن الجراح العسقلاني متروك."],[139,"وسمعته يقول: رجاء بن أبي رجاء مجهول، يروي عن مجاهد، وقيل هو رجاء بن الحارث."],[140,"وسمعته يقول: ريحان بن سعيد بصري يحتج به."],[141,"وسمعته يقول: ربعي٢ بن الجارود بن أبي بصرة. بصري لا بأس به."],[142,"وسمعته يقول: ربيعة بن سيف المعافري مصري صالح."],[143,"وربيع بن زيد الدمشقي يعرف بالقصير، يعتبر به."],[144,"وربيه الجرشي٣ يروي عنه ابن معدان. ثقة."],[145,"والربيع بن يحي الأشناني ٤ ضعيف ليس بالقوي يخطئ كثيرا."],[146,"وسمعته يقول: راشد ابن داود. أبو المهلب حمصي ضعيف لا يعتبر به."],[147,"وراشد بن سعد حمصي لا باس به. ويعتبر به إذا لم يحدث عنه متروك."],[148,"وسمعته يقول: رزيق بن أبي سلمى، يروي عن أبي المهزم، بصري يعتبر به. في حرف الزاي وسمعت أب الحسن رحمه الله يقول:"],[149,"زياد بن حدير١ عن ابن مسعود ثقة يحتج له."],[150,"وزياد بن عبد الله النخعي هو نخعي يعتبر به٢ لم يحدث به فيما أعلم غير العباس بن ذريح٣."],[151,"وزياد بن أبي زيد الجصاص، متروك متروك، بصري أقام بواسط."],[152,"وزياد بن الحسن بن فرات القزاز لا بأس به ولا يحتج به، كوفي.. وأبوه وجده ثقتان."],[153,"وزباد بن أبي مريم روى عن عبد الكريم الجزري: حراني ثقة."],[154,"وسمعته يقول: زكريا بن منظور٤ أبو يحي القرظي مدني متروك."],[155,"وزكريا بن يحي الطاحي متروك، بصري."],[156,"وزكريا بن أبي مريم () ٥ وقع إلى واسط حدث عنه هشيم لا بأس به."],[157,"وسمعته يقول: زيادة بن خراش يعتبر به له حديث عن ابن أبزى عن أبيه علي في الجنائز."],[158,"سألته عن حديث رواه الزبرقان بن عبد الله بن عمرو بن أمية عن زهرة عن زيد بن ثابت، فقال يخرج الحديث وزهرة١ مجهول."],[159,"زسمعته يقول: زيد بن سلام بن أبي سلام عن جده ثقتان. قال البرقاني رحمه الله: واسم أبي سلام ممطور."],[160,"وسمعته يقول: أبو أسامة زيد بن علي ثقة."],[161,"وسألته عن زيد بن إسحاق السلولي، فقال كنيته أبو إسحاق بصري يعتبر به."],[162,"وسألته عن زهير بن سالم عن ثوبان، فقال: هو حمصي منكر٢ لم يسمع من ثوبان."],[163,"وسألته عن زياد بن صبيح الجهني٣ فقال بصري يعتبر به."],[164,"وعن زفر بن الهذيل صاحب أبي حنيفة، فقال ثقة٤. في حرف السين"],[165,"وسمعته يقول: سعيد بن المرزبان، أبو سعد البقال، متروك."],[166,"وسعيد بن سلام، أصله بصري متروك. كان بمكة يحدث بالبواطيل."],[167,"وسعيد بن محمد الوراق كوفي يروي عنه أبو كريب. متروك."],[168,"وسعيد بن راشد هو السمالك، بصري متروك يروي عنه الأنصاري٥."],[169,"وسعيد بن زكريا أبو القاسم، كوفي ثقة."],[170,"وسعيد بن السايب الطايفي، يحدث عنه حرمي بن عمارة ثقة."],[171,"وسعيد بن سمعان عن أبي هريرة مدني ثقة."],[172,"وسعيد بن خالد القارظي١ يحدث عنه ابن أبي ذئب وابن إسحاق مدني يحتج به."],[173,"وسعيد بن عنبسة بصري يعتبر به."],[174,"وسعيد بن يزيد أبو شجاع يروي عنه ابن وهب ثقة من أهل مصر."],[175,"وسعيد بن عبيد الهانئ٢ بصري صالح."],[176,"وسعيد وعبد الله ابنا عبد الرحمن بن أبزى لأبيهما صحبة."],[177,"وقلت له سعيد بن زياد الشيباني عن زياد بن صبيح ابن عمر فقال: سعيد لا يحتج به ولكن يعتبر به من أهل البصرة لا أعرف له إلا حديث التصليب٣."],[178,"سمعته يقول سعيد بت إسحاق بن كعب بن عجرة مدني ثقة حدث عنه مالك."],[179,"وسعيد بن طريف كذاب"],[180,"وسمعته يقول بقية عن سليمان بن أبي داود حراني ضعيف.... وابنه محمد ضعيف أيضا، يلقب بالبومة."],[181,"وسمعته يقول: سليمان بن داود اليمامي يحدث عنه بشر بن الوليد متروك."],[182,"وسألته مرة أخرى فقال سليمان بن داود صاحب يحي بن أبي كثير متروك."],[183,"وسليمان بن أبي عثمان التجيبي مصري متروك١."],[184,"وسليمان بن كثير أبو داود الواسطي هو أخو محمد بن كثير البصري."],[185,"وسليمان بن عمرو بن عبد٢ ثقة هو أبو الهيثم يروي عن أبي سعيد الخدري."],[186,"وأبو الصباح سليمان بن يسير كوفي ضعيف٣."],[187,"قلت له: سيف٤ عن مجاهد عن ابن سخبرة، فقال هو سيف بن سليمان مكي ثقة."],[188,"وأبو سخبرة عبد الله بن سخبرة٥ أبو معمر صاحب ابن مسعود."],[189,"وسيف بن عمرو الأسيدي٦ كوفي متروك."],[190,"بن أبي مغيرة كوفي متروك."],[191,"وسيف بن محمد٧ متروك."],[192,"وسيف بن هارون البرجمي١ أخو سنان، ضعيف كوفي، متروك."],[193,"وسألته عن سلام بن المسكين بن سويد بن غفلة فقال كوفي."],[194,"وسألته عن سالم بن غيلان يروي عنه ابن وهب فقال بصري متروك."],[195,"قلت له: سلم عن الشعبي فقال قيل أن هذا مسلم بن عبد الرحمن النخعي فإن كان هذا فهو ثقة."],[196,"وسمعته يقول سويد بن إبراهيم الطحان أبو حاتم بصري ليس يعتبر به٢."],[197,"وسويد بن عبد العزيز الواسطي سكن الشام يعتبر به."],[198,"وسويد بن عمرو الكلبي كوفي ثقة."],[199,"سألته عن سوار بن داود أبي حمزة الصيرفي فقال: بصري لا يتابع على أحاديثه فيعتبر به، ثم قال لي: يحدث عنه وكيع فيخطئ في اسمه يقول داود بن سوار."],[200,"سمعته يقول: السفر بن بشير٣ حمصي ولا يعتبر به."],[201,"وسمير بن نهار عن أبي هريرة مجهول."],[202,"وسألته عن السايب بن حبيش٤ فقال من أهل الشام صالح الحديث حدث عنه زيادة ولا أعلم حدث عنه غيره."],[203,"وسمعته يقول: سنان بن هارون البرجمي أخو سيف يعتبر به."],[204,"وسلمة بن وردان مدني يترك. وفي حرف الشين"],[205,"سألته عن شعيب بن طلحة روى عن معن فقال: من ولد أبي بكر متروك."],[206,"وسألته: عن شعيب بن رزيق١ فقال: أبو شيبة، ثقة كان بطرسوس ثم سكن الرملة وعسقلان."],[207,"وسمعته يقول شرحبيل بن سعد يعتبر به، ضعيف حدث عنه مالك فقال: عن رجل٢."],[208,"وسمعته يقول شمر٣ بن عطية كوفي أسدي ثقة."],[209,"وسألته عن شداد بن سعيد فقال: بصري يعتبر به."],[210,"وقلت له: الأوزاعي عن أبي عمار فقال: هو شداد بن عبد الله ثقة وقال لي مرة أخرى شداد ابو عمار بصري ثقة."],[211,"وسمعته يقول: شهر بن حوشب يخرج من حديثه٤ ما روى عبد الحميد بن بهرام."],[212,"سألته عن شبل بن العلاء بن عبد الرحمن بن يعقوب الحرفي فقال ليس بالقوي ويخرج حديثه. في حرف الصاد قلت لأبي الحسن رحمه الله."],[213,"صدقة بن عيسى١ عن أنس قال متروك، كان بالبصرة ثم صار بالكوفة وقيل: عيسى بن صدقة."],[214,"قلت له: معمر عن صدقة عن ابن عمر، قال: هو ابن يسار ثقة مكي."],[215,"قلت: هشيم عن صدقة، فقال: هو ابن موسى يروي عن فرقد السبخي وأبي عمران الجوني متروك٢."],[216,"وسمعته يقول: الصلت بن طريف بصري لا بأس به."],[217,"والصلت بن بهرام من أهل الكوفة لا بأس به."],[218,"وسمعته يقول، الصباح بن محارب رازي يعتبر به."],[219,"والصباح بن يحي المزني٣ يروي عن الأعمش كوفي، ثقة."],[220,"وسألته عن صالح بن أبي الأخضر، فقال هو بصري لا يعتبر به، لأن حديثه عن ابن شهاب، عرض وكتاب وسماع فقيل له، يميز بينهما فقال لا٤."],[221,"وسمعته يقول: صفوان بن عمرو ويعتبر به."],[222,"وسمعته يقول: صفدي بن سنان بصري متروك، اسمه عمر. في حرف الضاد سمعت أبا الحسن يقول:"],[223,"الضحاك بن حمرة١ شامي سكن واسط يعتبر به."],[224,"والضحاك بن عبد الله القرشي، مدني ثقة يحتج به يروي عن أنس."],[225,"والضحاك بن مزاحم ثقة لم يسمع من ابن عباس شيئا."],[226,"وسمعته يقول: ضمام٢ بن إسماعيل متروك يحدث عن موسى بن وردان عن أبي هريرة."],[227,"قلت: الثوري عن أبي سنان، قال: ضرار بن مرة كوفي ثقة فاضل. في حرف الطا"],[228,"قلت لأبي الحسن: ابن فضيل عن أبي سفيان فقال: اسمه طريف السعدي ويقال: ابن شهاب متروك٣ يحدث عن أبي نضرة وغيره."],[229,"قلت له طليق٤ بن محمد عن عمران بن حصين فقال: مرسل وطليق لا يحتج به، ليس حديثه نيرا."],[230,"وسألته عن طعمة بن عمرو الجعفري الكوفي، فقال: ليس بحجة٥ ويعتبر به."],[231,"وسمعته يقول: أبو تميمة الهجيمي٦ اسمه طريف بن مجالد بصري ثقة."],[232,"وقلت له: الطيب بن سلمان عن عمرة، فقال شيخ ضعيف بصري. في باب العين ... من ذلك العباد له. سألت أبا الحسن الدارقطني رحمه الله ونضر وجهه وغفر لنا وله ولجميع المسلمين."],[233,"عن عبد الله بن كرز عن نافع فقال مجهول١."],[234,"وعن عبد الله بن جعفر٢ يحدث عن المقري فقال: هو والد علي."],[235,"وعن عبد الله بن عطاء، فقال: كوفي كان بمكة ليس به بأس."],[236,"وعن عبد الله بن زياد عن عمار وابن مسعود٣ فقال: هو أبو مريم الأسدي كوفي ثقة."],[237,"وعن عبد الله بن الزبير الباهلي يروى عن ثابت فقال: شيخ بصري صالح."],[238,"وعن عبد الله بن نافع مولى ابن عمر فقال: متروك."],[239,"وعن عبد الله بن الأسود القرشي شيخ ابن وهب فقال: مصري لا بأس به٤."],[240,"وعن عبد الله بن شريك العامري فقال: كوفي لا باس به، قلت يروي عن ابن عمر وأبي الزبير٥ فقال: سماع منهما."],[241,"سألته عن عبد الله بن هارون بن عنترة١ فقال متروك يكذب وأبوه يحتج به وحده."],[242,"أبو وكيع٢ يعتبر به روى عن علي رضي الله عنه."],[243,"وسألته عن عبد الله بن يزيد مولى المنبعث فقال: يعتبر به."],[244,"قلت ابن أبي فديك يروي عن عبد الله بن يزيد عن أبيه عن أبي هريرة فقال: إن كان هذا يزيد مولى المنبعث فهو ثقة."],[245,"سألته عن عبد الله بن نافع الصايغ، فقال: مدني فقيه يعتبر به."],[246,"وعن عبد الله بن الأجلح، فقال كوفي لا بأس به."],[247,"وعن عبد الله بن عبد الرحمن بن يعلى روى عنه وكيع فقال: طايفي يعتبر به."],[248,"وعن عبد الله بن عبد الرحمن بن معمر بن حزم فقال: أبو طواله٣، مدني ثقة."],[249,"وسمعته يقول: أبو عامر الهوزاني هو عبد الله بن نجي٤ حمصي لا بأس به."],[250,"سألته عن عبد الله بن محمد العدوي، يحدث عن علي بن زيد بن جدعان فقال: متروك."],[251,"قلت لأبي الحسن أبو صادق عن أبي هريرة فقال: اسمه عبد الله."],[252,"بن ناجد أخوربيعة بن ناجد كذا يقول أبو نعيم، ويقال أبو صادق اسمه مسلم بن يزيد ويقال هما رجلان أحدهما مسلم والآخر عبد الله بن ناجد."],[253,"وسمعته يقول عبد الله بن عقيل أبو عقيل، أثنى عليه أحمد، يروي عنه أبو النضر الكوفي."],[254,"وعبد الله بن عروة بن الزبير أحد الأثبات الثقات."],[255,"وعبد الله بن غابر١ أبو عامر الألهاني حمصي لا بأس به."],[256,"وعبد الله بن أبي الهذيل عن ابن مسعود كوفي."],[257,"وعبد الله بن حسين قاضي سجستان وقع إلى البصرة يعتبر به."],[258,"فقلت له روى عبد الله بن الحسن الهاشمي عن أمه عن جدته، فقال أمه فاطمة بنت الحسين وجدته هي فاطة الكبرى بنت النبي رضي الله عنها، لم تسمع أمه عنها٢ ويخرج حديثه."],[259,"فقلت له عبد الله بن الوليد عن أبيه عن أبي هريرة، فقال: ابن الوليد هو مصري لا يعتبر به ليس هو بالذي حدث عنه أحمد بن حنبل، وابن حجيرة هو عبد الرحمن بن حجيرة٣ مصري معروف، ولا يثبت هذا الحديث."],[260,"وسمعته يقول: إسماعيل بن عياش عن عبد الله بن دينار هو البهراني حمصي ضعيف لا يعتبر به. باب في عبد الرحمن"],[261,"وسألته عن أبي بكر عبد الرحمن بن وردان الغفاري يروي عن أنس فقال: مدني يعتبر به١ وليس بأخي سلمة بن وردان."],[262,"سألته عن عبد الرحمن بن أبي حدود عن أبي هريرة فقال: لا بأس به."],[263,"قلت له: عبد الرحمن بن بشر بن مسعود الأنصاري عن النبي صلى الله عليه وسلم فقال: مرسل، إنما يحدث عن أبي سعيد الخدري ويحدث عنه ابن سيرين."],[264,"سألته عن عبد الرحمن بن عبد الله بن دينار فقال: أخرج عنه البخاري وهو عند غيره، ضعيف فيعتبر به٢."],[265,"وسمعته يقول: عبد الرحمن بن حسان الكناني حمصي لا بأس به."],[266,"وعبد الرحمن بن الحارث بن هشام يروي عن علي سمع منه خليل المدني."],[267,"قلت له: عبد الرحمن بن علقمة عن النبي صلى الله عليه وسلم فقال: لا تصح صحبته ولا يعرف٣."],[268,"وسمعته يقول: عبد الرحمن بن مطعم هو أبو المنهال، ثقة."],[269,"وعبد الرحمن بن معاوية هو من ولد عتبة بن أبي سفيان."],[270,"قلت له: عبد الرحمن بن مهران عن أبي هريرة فقال: شيخ مدني يعتبر به."],[271,"قلت له: روى حفص بن غياث عن عبد الرحمن جليس مسعر، قال: مجهول."],[272,"قلت له: عبد الرحمن بن أبي ذباب عن أبيه عن عثمان فقال لا يعرف له غير هذا."],[273,"سألته عن عبد الرحمن بن١ النعمان الأنصاري فقال: متروك."],[274,"وعن عبد الرحمن بن نافع بن جبير الزهري فقال: مجهوا، وأبوه معروف."],[275,"وسمعته يقول عبد الرحمن بن عبد الملك بن أبجر٢ من أهل الكوغة ثقة."],[276,"سألته عن عبد الرحمن بن عبد الله بن سابط فقال: هو ابن أبي حميضة ثقة مكي يروي عن أبي أمامة."],[277,"وسألته عن عبد الرحمن بن محمد يروي عن السايب بن يزيد فقال: هو شيخ مدني لا أدري من هو، يعتبر به٣."],[278,"سألته عن عبد الرحمن بن إبراهيم يروي عن العلاء بن عبد الرحمن فقال هو بصري لا بأس به٤."],[279,"قلت له ابن أبي ذئب عن عبد الرحمن بن مهران عن عبد الرحمن٥ بن سعد، فقال هذا عبد الرحمن أيضا مدني يعتبر به. وعبد الرحمن بن سعد، صالح مدني كناه الزهري أبا حميد وسماه صفوان بن سليم."],[280,"عبد الرحمن – ثم سقط على كلمة قالها الدارقطني من الرقعة أظنها الأعرج١."],[281,"قلت له: عبد الرحمن الأصم روى عنه عبد الحكم قائد سعيد بن أبي عروبة قال: بصري ثقة٢."],[282,"وسمعته يقول عبد الرحمن بن أبي الرجال٣ ثقة مدني. عبد العزيز"],[283,"سألته عن عبد العزيز بن المطلب فقال: شيخ مدني يعتبر به."],[284,"وأبوه المطلب بن عبد المطلب بن حنطب ثقة."],[285,"وأخوه الحكم بن المطلب يقاربه يعتبر به."],[286,"قلت له: عبد العزيز بن جريج عن عائشة قال: مجهول، وقيل هو والد ابن جريج فإن كان هو فلم يسمع من عائشة٤، يترك هذا الحديث."],[287,"قلت له: عبد العزيز الدباغ عن الداناج عن عكرمة فقال: عبد العزيز هو ابن مختار القفة، والد اناج اسمه عبد الله بن فيروز ثقة، عن عكرمة سماع ر٢٩٩- وسمعته يقول: عبد العزيز بن عبد الله بن حمزة صاحب النبي صلى الله عليه وسلم حمصي متروك. عبد الملك قلت لأبي الحسن:"],[288,"عبد الملك عن أبي سلمة من هو؟ فقال: عبد الملك بن أبي سليمان ثقة."],[289,"وسمعته يقول: عبد الملك بن قدامة الجمحي مدني يترك."],[290,"وعبد الملك بن محمد بن نصير١ أبو حذيفة عنه، مجهولان."],[291,"وعبد الملك بن أبي زهير الثقفي يحدث عنه سعيد بن السايب الطائفي شيخ مقل ليس بالمشهور يخرج حديثه."],[292,"وعبد الملك بن عبد الملك روى عنه عمر بن الحارث مدني متروك. عبد الكريم"],[293,"قلت له عبد الكريم عن زياد بن أبي مريم، فقال: هو الجزري ثقة."],[294,"قلت فابن أبي ليلى عن عبد الكريم، فقال: هذا أبو أمية البصري يترك. عبد الواحد"],[295,"وسمعته يقول: عبد الواحد بن عبد الله النضري٢ ثقة من أهل حمص ولأي أمارة المدينة محمود الأمارة."],[296,"وعبد الواحد بن ميمون مولى عروة، كنيته أبو حمزة متروك صاحب مناكير٣."],[297,"وعبد الواحد بن أبي عون ثقة مدني يحدث عن سعد بن إبراهيم. عبد الحكيم"],[298,"سألته عن أبي سفيان الواسطي حدث عنه إسحاق بن شاهين فقال اسمه عبد الحكيم بن منصور متروك."],[299,"وسألته عن عبد الحكيم١ بن عبد الله بن أبي فروة فقال لي شيخ مقل مدني يعتبر به إذا حدث عن غير الواقدي."],[300,"قلت له فعبد الحكيم قائد سعيد بن أبي عروبة، فقال: بصري يترك. جماعة متفرقون سمعت أب الحسن الدارقطني رحمه الله يقول:"],[301,"عبد المنعم بن نعيم أبو سعيد الرياحي من أهل خوزستان متروك٢."],[302,"وعبد المنعم بن بشير مصري متروك٣."],[303,"وعبد الرحيم بن هارون الغساني متروك يكذب، واسطي إن شاء الله وكان ببغداد٤."],[304,"وعبد الغفار بن القاسم أبو مريم متروك، ثم قال: شيخ شعبة أثنى عليه شعبة وخفي على شعبة وبقي بعد شعبة فخلط٥."],[305,"وعبد المجيد بن عبد العزيز بن أب رواد١ لا يحتج به، ويعتبر به، وأبوه أيضا لين والإبن أثبت، قيل أنه مرجئ ولا يعتبر بأبيه يترك وهما مكيان."],[306,"وعبد الكريم بن عبد المجيد، هو أبو بكر الحنفي وهم أربعة إخوة هذا."],[307,"وأخوه عبيد الله بن عبد المجيد أبو علي وشريك وعمير، لا يعتمد منهم إلا على أبي بكر وأبي علي."],[308,"وعبد الوهاب بن الضحاك العرضي٢ متروك."],[309,"وعبد الأعلى بن عامر الثعلبي٣ روى عن ابن أبي ليلى، يعتبر به."],[310,"وعبد الحميد بن محمود كوفي يحتج به."],[311,"وعبد الحميد بن أمية عن أنس لا شيء."],[312,"وعبد القدوس بن الحجاج أبو المغيرة يروي عن الأوزاعي ثقة."],[313,"وعبد الجبار بن عمر الأيلي أبو عمر متروك."],[314,"عبيد بن خنيس٤ العبدي، قال الدارقطني متروك."],[315,"وعبيد بن الحشحاش٥ عن أبي ذر متروك."],[316,"وعبيد بن حسان قال لي: جزري متروك."],[317,"وعبيد بن الأسود يعتبر به."],[318,"وسمعته يقول: عباد بن أحمد العرزمي يحدث عنه المقانعي ١ متروك."],[319,"وعباد بن سعيد بصري، متروك يحدث عن مبشر ابن أبي المليح."],[320,"قلت له: أبو ظفر عبد السلام بن مطهر بن الحسام بن مصك بن شيطان شيخ أبي خليفة، كذا نسبه، قال نعم، بصري ثقة."],[321,"وسألته عن عبد الرزاق بن عمر الدمشقي، فقال: ضعيف، فقيل من أي شيء ضعفه، فقال قيل أن كتابه عن الزهري ضاع، فقيل هو في معنى صالح بن أبي الأخضر؟ فقال. ذاك فوق عبد الرزاق.٢ وسألت عنه مرة أخرى فقال: هو ضعيف يعتبر به ويكنى أبا بكر. آخر الجزء الأول ويتلوه في الجزء الثاني الذي يليه باب بقية العين. بسم الله الرحمن الرحيم قال أبو بكر أحمد بن محمد بن أحمد بن غالب البرقاني الحافظ: سألت الحافظ أبا الحسن بن عمر الدارقطني رحمه الله قلت له:"],[322,"عنبسة١ بن سعيد بن العاص عن أبي هريرة فقال: هذا جليس الحجاج وهو عم إسماعيل بن أمية."],[323,"قلت: فعنبسة بن سعيد بن كثير قال: هو ابن أبي العنبس كوفي يعتبر به."],[324,"قلت: فعنبسة بن سعيد القطان قال: هذا أخو أبي الربيع السمان بصري متروك٢."],[325,"قلت: فعنبسة بن سعيد الأموي فقال: هذا اخو يحي ومحمد وعبد الله وعبيد وأبان، كلهم ثقات٣."],[326,"وسمعته يقول: عاصم الأحول عداده في البصريين، وعاصم بن أبي النجود٤، والأحول أثبت ثم قال لي: ابن أبي النجود في حفظه شيء."],[327,"وعاصم بن عبيد الله المدني يترك، هو مغفل."],[328,"وعاصم بن هلال، أبو النضر بصري لا بأس به."],[329,"قلت له: فعاصم بن حميد السكوني يروي عن معاذ، قال هو من أصحابه ثقة."],[330,"سألته عن عامر بن صالح بن عبد الله بن عروة بن الزبير بن العوام شيخ أحمد بن حنبل ويحي بن معين، فقال أساء القول فيه ابن معين١، ولم يتبين أمره عند أحمد٢ وهو مدني يترك عندي."],[331,"قلت: فعامر بن جشيب٣ يروي عن أبي الدرداء قال: حمصي ثقة لم يسمع من أبي الدرداء."],[332,"وسألته عن عامر بن عبيدة الباهلي فقال: بصري لا بأس به."],[333,"سالت أبا الحسن عن عمر بن راشد المدني يروي عن هشام بن عروة ومالك بن عبد الرحمن بن حرملة، فقال: يقال له الجاري كان يكون بالجار متروك٤."],[334,"وسمعته يقول: عمر بن عبد الرحمن بن قيس بن الأبار٥ أبو حفص كوفي ثقة."],[335,"وسألته عن عمر بن موسى الأنصاري، فقال كوفي متروك."],[336,"وعن عمر بن خالد القى، فقال: لا بأس يه."],[337,"وسئل عن عمر بن إبراهيم يروي عن قتادة فقال: بصري لين يترك."],[338,"وعن عمر بن يزيد فقال: كوفي أزدي كنيته أبو سعيد، متروك روى أبو كريب عنه."],[339,"قلت له: فعمر بن وهب الخزاعي، قال بصري معروف لا بأس به لا يعرف اسم أبيه١."],[340,"قلت: روى المقانعي٢ عن عمر بن محمد بن الحسن عن أبيه، قال لا بأس بهما."],[341,"قلت: عمر بن بشير بن المحرر عن أبيه، ويقال عمران بن بشير، قال: حدث عن أبيه، سعيد المقبري، يعتبر به وأبيه بشير."],[342,"وسمعته يقول: عمر بن زرارة الحدثي٣ ثقة، من مدينة في الثغر يقال لها الحدث."],[343,"فأما عمرو بن زرارة فهو نيسابوري ثقة أيضا."],[344,"سالته عن عثمان بن عمير أبي اليقظان، فقال كوفي يعتبر به."],[345,"قلت: وكيع عن عثمان الحشام٤ فقال هو بصري يعتبر به."],[346,"قلت فعثمان بن واقد، قال عمري كوفي لا بأس به يحدث عن نافع."],[347,"وسمعته يقول: عثمان بن مسلم البتي٥ ثقة."],[348,"قلت له: روى هشيم عن عثمان بن حكيم عن سهل بن حنيف، فقال: أخطأ في نسبه إنما هو عثمان بن حكيم بن عباد بن حنيف أخو سهل بن حنيف."],[349,"سألته عن علي بن زيد بن جدعان. فقال: هو علي بن زيد بن جدعان بن عبد الله بن أبي مليكة بن عبد الله بن جدعان، ثم قال لي: أنا أقف فيه لا يترك عندي. فيه لين.١."],[350,"وسئل عن علي بن هاشم بن البريد فقال: قال أحمد هو أول من كتبنا عنه٢."],[351,"وسألته عن علي بن غراب٣ فقال كوفي يعتبر به."],[352,"وعن علي بن عابس٤ فقال: كوفي يعتبر به."],[353,"وعن علي بن خلف الدؤلي، فقال: شيخ مدني يعتبر به."],[354,"وعن علي بن الحسين بن أبي بردة،.فقال: كوفي صالح."],[355,"وعن علي بن أبي فاطمة٥ يحدث عنه يونس بن بكير، فقال مجهول يترك."],[356,"وعن علي بن الحسن الشامي، فقال مصري يكذب يروي عن الثقات بواطل مالك والثوري وابن أبي ذئب."],[357,"سمعته يقول عمرو بن مالك الجنبي ١ أبو علي، مصري لا بأس به، ثم قال ثقة."],[358,"وعمرو بن أبي الحجاج ثقة مصري، هو والد أبي معمر المنقري صاحب عبد الوارث."],[359,"وعمرو بن شمر كوفيي متروك."],[360,"وعمرو بن أبي نعيمة المعافري مجهول مصري يترك٢."],[361,"وعمرو بن خالد أبو حفص الأعشى متروك. وقال مرة أخرى عمرو بن خالد الواسطي متروك٣ يحدث عن زيد بن علي وأبي هاشم الرماني وحبيب بن أبي ثابت."],[362,"وسألته عن حديث عمارة بن غزية عن أنس عن عمر عن النبي صلى الله عليه وسلم في فضل عمارة٤ فقال مرسل لم يلحق عمارة أنسا، وهوثقة."],[363,"وسمعته يقول عمارة بن زاذان الصيدلاني بصري ضعيف لا يعتبر به."],[364,"وأبو معشر عمارة بن صدقة كوفي يحدث عنه أبو كريب، ثقة."],[365,"وعمار بن سيف الضبي كوفي متروك."],[366,"وعمار بن يزيد مجهول يحدث عن موسى بن هلال الطويل."],[367,"وعمران بن الجعد وقيل ابن أبي الجعد كوفي١ ثقة يحدث عن عمر، مرسل."],[368,"وعمير بن مأمون عن الحسن بن علي، لا شيء. سمعت أبا الحسن يقول:"],[369,"عون بن سلام٢ لا بأس به."],[370,"وعون بن ذكوان القصاب، بصري أبو جناب متروك."],[371,"وعون مولى أم حكيم عن الزهري مديني ثقة.٣."],[372,"وعون بن معمر شيخ خرساني سكن البصرة ليس به بأس٤."],[373,"وعون بن عبد الله٥ عن عبد الله بن مسعود مرسل."],[374,"عيسى بن المختار بن عبد الله بن أبي ليلى ثقة."],[375,"وعيسى بن ميسرة أبو عيسى الخياط متروك٦ وأخوه موسى يعتبر به."],[376,"وعيسى بن عمر يحدث عنه عمرو بن يحي بن عمارة، هو مديني معروف يعتبر به."],[377,"وعيسى بن مسلم هو أبو داود الطهوي من بني طهية كوفي متروك."],[378,"قلت له محمد بن زيد بن مهاجر عن ابن سيلان من هو؟ ١ فقال: قد قيل اسمه عيسى وقيل عبد ربه مديني يعتبر به."],[379,"قلت له عيسى بن صدقة٢ قال لا شيء."],[380,"سمعته يقول: أبو النجاشي عن رافع اسمه عطاء بن صهيب وقيل غير هذا."],[381,"عباس بن ذريح كوفي ثقة."],[382,"وعوسجة بن الرماح٣ شبه مجهول لا يروي عنه غير عاصم لا يحتج به لكن يعتبر به."],[383,"عتيق بن يعقوب الزبيري مديني ثقة وهو ابن صديق بن موسى٤ بن عبد الله بن الزبير، حدث عن ابن جريج عن صديق."],[384,"عتبة أبو عمر كوفي شيخ لا بأس به، يحدث عن ابن نهشل مجهول يترك حديثه."],[385,"قلت له: فعتبة بن عمرو بن أبي هريرة قال: هو ابن عمرو بن عباس قرشي ثقة، وقال بعضهم: عتبة بن عمرو عن ابن عباس وهذا خطأ."],[386,"سالته عن عفيف بن سالم الموصلي فقال: ربما أخطأ لا يترك."],[387,"قلت له: عدي بن ثابت عن أبيه عن جده عن النبي صلى الله عليه وسلم قال لا يثبت ولا يعرف أبوه ولا جده، وعدي ثقة."],[388,"وقال لي: عدي بن الفضل بصري متروك."],[389,"قلت فعدي بن أرطأة عن عمرو بن عنبسة فقال بصري، يحتج به١."],[390,"قلت عجلان عن أبي هريرة قال هو مولى المشمعل يعتبر به."],[391,"وسمته يقول عكرمة بن عمار يمامي ثقة."],[392,"وعكرمة بن إبراهيم الأزدي كان من أهل الكوفة أقام بالبصرة٢."],[393,"عياض بن دينار عن أبي هريرة لا أعلم حدث به، غير ابن إسحاق يعتبر به."],[394,"عصام بن قدامة البجلي٣ كوفي يعتبر به."],[395,"وعلوان أبو رهم مجهول يترك، لا يحدث عنه غير ليث بن أبي سليم."],[396,"ابن عتبة أبي الصهباء أبو خريم بصري ثقة."],[397,"عبدوس بن كثير٤ حدثونا عنه لا بأس به من أهل الري، حدث ببغداد قبل الستين يعتبر به."],[398,"وسمعته يقول: عياش بن عقبة الحضرمي ليس به بأس، يقول المقرئ هو ابن لهيعة١ وليس كذلك، ابن لهيعة هو عبد الله بن لهيعة بن عقبة بن أبي عبد الرحمن وهذا ابن عقبة بن فلان بن تغلب."],[399,"وسألته عن عراك بن خالد فقال: لا بأس به."],[400,"قلت له عصمة بن بشير بن الفرع عن المنتفع صاحب النبي صلى الله عليه وسلم، فقال عصمة مجهول، والفرع كذلك، والمنتفع أعرابي من أصحاب النبي صلى الله عليه وسلم٢."],[401,"سمعته يقول: عروة بن رويم٣ شامي لا بأس به. في حرف الغين"],[402,"سمعته يقول: غيلان بن عبد الله عن ابن عمر هو مولى بني مخزوم. ثقة."],[403,"وقلت له: غضيف٤ بن الحارث قال: ثقة من أهل الشام. في حرف الفاء"],[404,"سألته عن الفرج بن فضالة، فقال ضعيف."],[405,"وسمعته يقول: فضيل بن ميسرة أبو معاذ بصري٥. في حرف القاف"],[406,"سألته عن قابوس بن أبي ظبيان، فقال: ضعيف ولكن يترك."],[407,"قلت له: قريش بن إبراهيم عن عبد الرحمن بن عبد الملك بن أبجر. فقال: قريشي بغدادي لا بأس به.١. في حرف الكاف"],[408,"سمعته يقول: كريز بن حكيم كان بحلب، منكر الحديث. في اللام"],[409,"سألته عن ليث بن أبي سليم، فقال: صاحب سنة يخرج حديثه، ثم قال أنكروا عليه الجمع بين عطاء وطاووس ومجاهد حسب٢ باب الميم"],[410,"سألته عن محمد بن إسحاق بن يسار عن أبيه، فقال لا يحتج بهما٣ وإنما يعتبر بهما."],[411,"وسألته عن محمد بن إبراهيم بن العلاء الشامي فقال: كذاب."],[412,"سمعته يقول: محمد بن أيوب بن سويد الرملي متروك. وأبوه يعتبر به."],[413,"ومحمد بن جعفر بن الزبير يروي عن عروة مدني يعتبر به٤."],[414,"ومحمد بن حمير عن الأوزاعي حمصي لا بأس به."],[415,"ومحمد بن الحسن بن زبالة١ المخزومي متروك."],[416,"ومحمد بن دينار الطاحي٢ بصري متروك وقال مرة ضعيف."],[417,"وسالت أب الحسن بن مظفر عن محمد بن دينار فقال لا بأس به٣."],[418,"سمعت الدارقطني يقول: محمد بن ربيعة الكلابي يروي عنه أبو كريب ثقة."],[419,"ومحمد بن راشد المكحولي، كان بالبصرة يعتبر به. وسمعته مرة أخرى يقول: محمد بن راشد الضرير بصري يحدث عن روح بن القاسم بن عبيد ليس بالقوي، يعتبر به. وسمعته مرة أخرى يقول: محمد بن راشد الكوفي ثقة يحدث عن يحي."],[420,"وسمعته يقول: محمد بن أبي إسماعيل ومحمد بن راشد عن أبيه عن أم الدرداء، مقل لا أعرف له سندا."],[421,"ومحمد بن زيد بن مهاجرين قنفذ مدني قال مرة: يحتج به، وقال مرة أخرى: يعتبر به."],[422,"محمد بن أبي حفصة أبو سلمة، صالح بصري يعتبر به."],[423,"محمد بن سوقة٤ بن عمير هو مولى جرير بن عبد الله، كوفي فاضل ثقة. محمد بن سعيد أبو عبد الرحمن قتل في الزندقة١ يعرف بالمصلوب يحدث عن ربيعة بن يزيد الدمشقي."],[424,"وسمعته يقول: الحميدي عن محمد بن أبي شيبة من ولد كعب بن مالك مديني أنصاري، لا بأس به مقل."],[425,"قلت له: أبو عثمان محمد بن شريك المكي من هو؟ فقال ثقة معروف يحدث عنه وكيع وأبو نعيم وغيرهما."],[426,"سألته عن محمد بن صالح يروي عنه زيد بن الحباب، فقال هو التمار همداني متروك."],[427,"قلت له: شريك عن محمد بن عبد الرحمن عن عطاء قال: يشبه أن يكون ابن أبي ليلى."],[428,"وسمعته يقول: محمد بن عبد الله بن عبيد بن عمير، يحدث عن أبيه عن جده عن النبي صلى الله عليه وسلم متروك."],[429,"ومحمد بن عبد الرحمن بن محمد بن عبد الله بن أبي سليمان العرزمي هو عم عباد بن أحمد العرزمي٢ وأبو سليمان ميسرة هو الفزاري."],[430,"ومحمد بن عبد الرحمن متروك وأبوه وجده."],[431,"قلت: محمد بن عبد الرحمن بن طلحة القرشي، فقال متروك ولا أدري من أين هو."],[432,"وسمعته يقول: محمد بن عبد الرحمن بن عبد الله بن الحارثة بن النعمان هوأبو الرجال١ وأمه عمرة بنت عبد الرحمن بن أسعد بن زرارة، ويقال له سعد بن زرارة، وليس بصحيح هو ابن أخي عمرة بنت عبد الرحمن."],[433,"محمد بن عبد الملك الدقيقي ثقة. قلت لأبي الحسن:"],[434,"محمد بن عياش بن عمرو العامري عن الأعمش فقال: صالح عزيز الحديث حدث الثوري عن أبيه٢."],[435,"قلت: محمد بن عثمان الواسطي عن ثابت البناني قال: مجهول."],[436,"قلت: محمد بن عمرو بن الخليل، قال لا أعرفه٣."],[437,"قلت: محمد بن عبدة بن الحكم٤ قال مروزي ثقة وأبوه ثقة."],[438,"قلت: محمد بن عون مولى أم حكيم، قال مديني ثقة يحدث عن أبيه."],[439,"قلت: محمد بن الفضل بن عطية الخرساني، قال: متروك."],[440,"قلت: محمد بن القاسم بن عبد الرزاق الجمحي قاضي مكة يحدث عن جبارة، قال: صالح."],[441,"قلت محمد بن أبي كريب٥ مولى ابن عباس قال متروك."],[442,"قلت: محمد بن كليب يحدث عن جابر قال: مقل يعتبر به."],[443,"قلت: محمد بن معاوية النيسابوري حدث عنه مطين وغيره، قال كان بمكة يضع الحديث متروك١."],[444,"قلت: محمد بن مسلم بن مهران بن المثنى قال: بصري يحدث عن جده لا بأس بهما."],[445,"قلت: محمد بن مروان القطان، قال شيخ من الشيعة حاطب ليل لا يكاد يحدث عن ثقة، متروك."],[446,"وسمعته يقول: محمد بن محصن ويقال ابن إسحاق الأندلسي والعكاشي٢ عن الثوري والأوزاعي وابن عجلان وابن أبي عبلة متروك يضع."],[447,"محمد بن مهاجر أخو حنيف بغدادي متروك."],[448,"وحمد بن النوار بصري ثقة."],[449,"وحمد بن الوليد بن نويفع من أهل المدينة يعتبر به."],[450,"محمد بن واسع الأزدي بصري عابد ثقة، قلت هو الذي يحدث عن سالم بن عبد الله بن عمر قال: نعم، ثم قال: إلا أنه بلي برواة عنه ضعفاء."],[451,"قلت له: محمد بن يحي بن قيس المدايني، قال يحدث عن ابن جريج ثقة، وأبوه كذلك."],[452,"قلت: محمد بن يحي بن فياض الزماني٣ يحدث عنه ابن غنام قال بصري ثقة."],[453,"قلت محمد بن يوسف مولى عمرو بن عثمان عن أبيه عن معاوية، قال محمد ثقة من أهل المدينة وأبوه لا بأس به سمع من معاوية. سألت عن حديث نافع بن سليمان عن محمد بن أبي صالح عن أبيه عن عائشة \" الإمام ضامن\"."],[454,"قال: محمد هذا مجهول وقيل هو أخو سهيل يترك هذا الحديث١."],[455,"سألته عن محمد بن الحسن صاحب أبي حنيفة رحمه الله، فقال: قال يحي بن معين كذاب، وقال فيه أحمد يعني بن حنبل نحو هذا، قال أبو الحسن: وعندي لا يستحق الترك٢."],[456,"وسمعته يقول: محمد بن جابر وأيوب بن جابر أخوان ضعيفان متقاربان، قيل له: يتركان، قال: لا يعتبر بهما٣."],[457,"قلت روى هشيم عن محمد بن عبد الرحمن القرشي من هو؟ فقال شيخ."],[458,"قلت: محمد بن الحسن الهمداني عن جعفر بن محمد يروي عنه شريح بن يونس فقال: كوفي لا شيء."],[459,"سمعته يقول: شريح بن يونس عن محمد بن الحجاج اللخمي، كذاب من أهل واسط هو صاحب حديث الهريسة٤."],[460,"ومحمد بن عثمان بن صفوان بن أمية الجمحي من أهل مكة، ليس بالقوي١ تفرد بحديث عن هشام بن عروة في الزكاة٢."],[461,"وسألته عن حديث لحسان بن علي عن محمد بن عبيد الله بن أبي رافع عن أبيه عن جده، قال لي: لا تخرجه هذا محمد بن عبيد الله متروك له معضلات هو من أهل الكوفة."],[462,"قلت له: روى ابن عيينة عن أبي فروة قال: هو مسلم بن سالم لا بأس به."],[463,"قلت له: أبو حمزة عن إبراهيم، قال اسمه ميمون."],[464,"وسمعته يقول: مبارك بن فضالة لين كثير الخطأ بصري يعتبر به."],[465,"ومحارب بن دثار٣ ثقة."],[466,"ومحل بن محرز ٤ الضبي ثقة كوفي."],[467,"ومحل بن خليفة ثقة."],[468,"ومدر أبو زياد عن عائشة مجهول٥."],[469,"ومثنى بن بكر يحدث عن فايد أبي الورقاء بصري متروك."],[470,"ومهران بن المثنى أبو جعفر عن ابن عمر لا بأس به، حدث عنه إسماعيل بن أبي خالد."],[471,"ومجالد بن سعيد الكوفي ليس بثقة، يزيد بن أبي زياد أرجح منه، ومجالد لا يعتبر به."],[472,"ومرثد١ بن عبد الله اليزني أبو الخير ثقة."],[473,"ومبشر بن أبي المليح عن أبيه لا بأس به ويحتج بحديثه وأخواه زياد ومحمد يحدثان عن أبيهما أيضا يعتبر بهما."],[474,"ومهدي بن عيسى أبو الحسن الواسطي الطحان عن أبي الزناد لا بأس به."],[475,"قلت له: أبو الأحوص عن أبي فروة قال: هو مسلم بن سالم النهدي٢ كوفي لا باس به."],[476,"قلت ابن أبي ذئب عن مسلم الحطاب عن ابن عمر قال هو: مدني ثقة."],[477,"قلت مسلم بن الحارث التميمي عن أبيه عن النبي صلى الله عليه وسلم قال: مسلم مجهول، لا يحدث عن أبيه إلا هو٣."],[478,"قلت: مسلم الأعور، قال متروك وقال لي مرة أخرى: مسلم بن كيسان الأعور بياع السابري، ضعيف ليس يستحق أن يترك٤."],[479,"قلت: مسلم بن يسار، قال أبو عثمان الطنبذي٥ من أهل مصر لا يعتبر به."],[480,"وسمعته يقول: مسلم بن عبيد أبو نصيرة، ليس ممن يحتج به يشبه أن يكون واسطيا١."],[481,"ملازم بن عمرو يمامي ثقة، أقام بالبصرة، قلت حديثه عن عبد الله بن بدر اليمامي عن قيس بن طلق عن أبيه، قال: كلهم من أهل اليمامة وهذا إسناد مجهول يخرج."],[482,"قلت حديث بن أبي سليم عن رجل عن أنس بن مالك رضي الله عنه عن النبي صلى الله عليه وسلم في \" النوم عن النوم قبل العشاء والحديث بعدها\"، قال: الرجل هو مسلم الأعور."],[483,"قلت: مالك بن نمير الخزامي عن أبيه، قال: لا يحدث عن أبيه إلا هو، يعتبر به ولا بأس بأبيه٢."],[484,"قلت: مالك بن دينار، قال ثقة، ولا يكاد يحدث عنه ثقة."],[485,"قلت: مالك بن أبي الرجال قال صالح، حدث الواقدي وأبو علي الحنفي عنه، ويقول الحنفي: مالك بن محمد بن أبي الرجال.٣."],[486,"قلت موسى بن وردان عن أبي هريرة، قال لا بأس به."],[487,"قلت: موسى بن ثوران، قال: ويقال بن سروان عن طلحة بن عبيد الله بن كريز عن عائشة رضي الله عنها، إسناد محمول حمله الناس٤."],[488,"قلت له: أبو خلف موسى بن خلف، قال بصري ليس بالقوي يعتبر به حدث عنه عثمان."],[489,"قلت موسى بن هلال الطويل عن أنس قال: متروك."],[490,"قلت موسى بن عبد الله بن يزيد بن زيد، قال: ثقة وأبوه وجده١ صحابيان."],[491,"قلت له: موسى بن أنس بن مالك بن عمه ثمامة عن جده أنس بن مالك رضي الله عنه، قال: يخرج الحديث اعتبارا وموسى كوفي."],[492,"وسمعته يقول: موسى بن محمد أبو عمران يقال له: ابن العلي الشطوي٢ حدث عنه ببغداد ضعيف يترك."],[493,"موسى بن نصر الرازي أبو سهل٣."],[494,"مصعب بن المقدام ثقة."],[495,"ومصعب بن أبي ذئب عن القاسم بن محمد مني متروك."],[496,"مغيرة بن مسلم يحدث عنه مروان بن معاوية خراساني لا بأس به."],[497,"ومعين بن زياد موصلي يحدث عنه وكيع يعتبر به."],[498,"ومغيرة بن سبيع٤ عن ابن بريدة كوفي يحتج به."],[499,"معضل بن إسماعيل التيمي كوفي لا بأس به."],[500,"معروف بن واصل كوفي يكنى أبا بدل٥."],[501,"مروان بن شجاع ثقة جزري."],[502,"قلت له: روى الوليد بن مسلم عن مروان بن جناح، قال: لا بأس به شامي أصله كوفي١. في باب النون والهاء"],[503,"سألته عن نهشل عن الضحاك، هو ابن مزاحم قال: نعم."],[504,"قلت: نهشل ابن من؟ قال: ابن سعيد الدارمي لا شيء."],[505,"وسألته عن عدي بن الفضل، قال: يترك، ثم قال: وأبو جزي نصر بن طريف أسو حالا منه٢."],[506,"قلت له: نابل صاحب العباء٣ عن ابن عمر هو ثقة، فأشار أن لا."],[507,"وسمعته يقول: نسير بن ذعلوق٤ من أهل الكوفة ثقة."],[508,"والنضر بن طاهر. بصري مبروك."],[509,"همام عن أبي غالب. اسمه نافع. ثقة. يحدث عن أنس."],[510,"قلت. نعمان عن ابن عباس. قال مجهول يحدث عنه أبو عجلان."],[511,"وسمعته يقول. نسير بن ذغلوق (٤) من أهل الكوفة ثقة."],[512,"قلت له: أبو معاذ نهار بن عثمان القناد شيخ ابن ناجية كيف هو؟ قال: شيخ بصري، لم يزدني على هذا."],[513,"قلت له: روى سريج بن يونس عن أبي الحسين هارون بن مسلم، قال صاحب الحناء، بصري صويلح يعتبر به."],[514,"وسمعته يقول: الهجنع بن قيس لا شيء وهو كوفي وله حديثان١. باب الواو٢ باب الياء سمعت أبا الحسن يقول:"],[515,"يحي الجابر هو ابن عبد الله التيمي كوفي يعتبر به."],[516,"محبر لا يتابع على أحاديثه، ولا يكاد يروي عن شيوخه غيره."],[517,"ويحي بن عبد الله بن سالم بن عبد الله ثقة مدني حديثه بمصر."],[518,"قلت أبوه، قال: لا أعلم لأبيه حديثا."],[519,"ويحي بن عبد الرحمن الأرحبي٣ كوفي صالح يعتبر به يروي عنه أبو كريب."],[520,"قلت له: يحي بن عبد الرحمن بن حاطب عن ابن عمر، قال ثقة حدث عنه عروة وهو أيضا حدث عن عروة."],[521,"قلت يحي بن عبد الملك بن حميد بن أبي غنية١ يحدث عنه أبو بكر ابن أبي شيبة. قال: ثقة وأبوه ثقة."],[522,"قلت ابن دينار، قال: أبو هاشم الرماني: ثقة."],[523,"يحي بن عباد الضبعي أبو عباد، قال بغدادي يحتج به."],[524,"قلت: يحي بن عباد بن عبد الله بن الزبير عن أبيه عن معاوية، قال: سماع أبيه عن معاوية لا يصح إلا أنه أدركه، ويحي وأبوه عباد ثقتان."],[525,"قلت يحي بن سعيد بن أبان بن سعيد بن العاص الأموي، قال ثقة."],[526,"قلت يحي بن سلمة بن كهيل قال: متروك، وابنه إسماعيل بن يحي كذلك، وأخوه محمد بن سلمة بن كهيل يعتبر به."],[527,"قلت: يحي بن قيس المازني يحدث عنه البرساني، قال: ثقة من ناحية اليمن."],[528,"قلت: يحي بن المهلب قال: أبو كدينة٢ يعتبر به."],[529,"قلت: يحي بن معاذ الدسري، قال: يعتبر به."],[530,"وسمعته يقول: يحي بن هانئ يحدث عن أبو بكر بن عياش والثوري كوفي يحتج به."],[531,"قلت له: قتادة بن مالك، قال: هو أبو أيوب العتكي٣ مراغي. ثقة سمع من سمرة."],[532,"قلت يحي بن ميمون، قال ثقة قاضي مصر. سمع من سهل بن سعد حينما دخل مصر."],[533,"قلت يحي بن أبي سليم أبو بلج١ قال: واسطي ثقة."],[534,"قلت حماد عن أبي المعلا العطار، قال: اسمه يحي بصري لا يعتبر به."],[535,"سألت أبا الحسن عن يزيد بن ربيعة عن أبي الأشعث قال دمشقي متروك."],[536,"وعن يزيد بن صليح٢ قال حمصي لا يعتبر به."],[537,"وعن يزيد بن يوسف الدمشقي، فقال: متروك حمري يروي عن الأوزاعي وقال لنا مرة أخرى اختلفوا فيه فيحي بن معين يغمز عليه٣ وليس يستحق عندي الترك."],[538,"وسألته عن يزيد بن زيد مولى أبي أسيد البدري فقال: مجهول٤ متروك."],[539,"وعن يزيد بن أبي سفيان فقال: أبو المهزم بصري، أساء القول فيه شعبة، يترك."],[540,"وعن يزيد بن كميت شيخ للحسين العتاب فقال: كوفي متروك."],[541,"قلت محمد بن فضيل عن أبي إسماعيل الأسدي فقال: هو يزيد بن كهيل كوفي ثقة."],[542,"سألته عن يزيد بن عبد العزيز بن سياه فقال: كوفي ثقة."],[543,"قلت يزيد بن يعفر عن الحسن قال: بصري معروف يعتبر به."],[544,"قلت يزيد بن طلق، قال: يعنبر به."],[545,"قلت يزيد بن شريح قال: حمصي يعتبر به."],[546,"قلت يزيد بن بابنوس١ عن عائشة قال: بصري لا بأس به."],[547,"وسمعته يقول: يزيد بن محمد بن سنان الرهاوي هو أبو فروة وجده متروك."],[548,"وسألته عن يزيد بن أبي زياد فقال: لا يخرج عنه في الصحيح ضعيف يخطئ كثيرا (ويتلقن إذا لقن) ٢."],[549,"وسمعته يقول: يحسن٣ عن عائشة مولى ثقة بصري كنيته أبو موسى."],[550,"وسمعته يقول: يونس بن ميسرة بن حلبس٤ ثقة دمشقي."],[551,"وسألته عن يوسف بن سيف فقال: حمصي ثقة."],[552,"قلت يونس بن أبي يعفور يروي عن أبيه قال: كوفيان ثقتان."],[553,"قلت له: يعقوب بن عتبة بن المغيرة بن الأخنس قال: مديني ثقة، يروي عن عروة عن الزهري."],[554,"سألته عن أبي يوسف١ صاحب أبي حنيفة فقال: هو أقوى من محمد بن الحسن."],[555,"وسمعته يقول: يعقوب بن إسحاق أبو عمارة الرازي ثقة حدث عنه سريج بن يونس والحسن بن عرفة وعبد الحميد بن سنان."],[556,"وسألته عن يوسف بن عطية فقال: هما اثنان متروكان أحد هما بصري أبو سهل وهو الصفار يحدث عن ثابت وقتادة، والآخر كوفي كنيته أبو المنذر يحدث عن أبي حمزة مجهول٢. في الكنى وغير ذلك"],[557,"قلت لأبي الحسن: أبو أويس صاحب الزهري، قال: اسمه عبد الله بن عبد الله بن أويس بن مالك بن أبي عامر وهو بن عم مالك بن أنس٣ من أهل المدينة سماعه مع مالك عن الزهري. قلت: كيف حديثه عن الزهري قال: في بعضها شيء. سألته عن هذين الإسنادين: ملازم بن عمرو عن عبد الله بن بدر عن قيس بن طلق عن أبيه ن النبي صلى الله عليه وسلم. وعبد الله بن بدر عن عبد الرحمن بن علي عن أبيه عن بن شيبان عن النبي صلى الله عليه وسلم، حملهما الناس ويخرجان."],[558,"قلت: علي بن شيبان صحابي، قال: نعم١."],[559,"وسمعته يقول: أبو سعيد مولى بني هاشم اسمه عبد الرحمن بن عبد الله٢."],[560,"وأبو نعامة السعدي، عبد ربه بصري صالح."],[561,"الحسن وعلي ابنا صالح بن حي وهما أخوان لا ثالث لهما ثم قال وغلط ابن الجعابي فقال: صالح بن صالح هو أخوهما فوافقته فتبين (له) ٣ أنه أخطأ."],[562,"موسى بن وردان كان بمصر."],[563,"وعبد الرحمن بن وردان أبو بكر الغفاري مدني صالح يحدث عن أنس."],[564,"وسلمة بن وردان مدني ليس بينهم قرابة٤."],[565,"أبو حمزة الذي يقول شعبة جارنا اسمه عبد الرحمن بن أبي عبد الله."],[566,"وحدث هشيم عن أبي حمزة الأسدي قال شهدت ابن عباس، وهو آخر وهو أيضا واسطي ليس بالقوي."],[567,"وذكر له وأنا أسمع حديث السواك الذي رواه أبو الصقيل، فقال: أبو علي لا بأس به٥ ثم قال في الحديث اضطراب فيه منه."],[568,"وسمعته يقول: الجريري عن أبي الورد شيخ له، ما حدث عنه غيره١."],[569,"وسألته عن حديث الدراوردي عن محمد بن عثمان بن عبد الرحمن بن سعيد بن يربوع عن جده فقال: محمد مديني ثقة، وجده تابعي وسعيد بن يربوع له صحبة يكنى أبا هود. أخو عبد الله وعبيد الله وأبي بكر بني عمر هم أربعة."],[570,"فأما عاصم فضعيف قريب من عبد الله."],[571,"وأبو بكر بن عمر قليل الحديث بمرة ثقة. وقد تكلم أبو عبد الرحمن النسائي على أحمد بن صالح حيث قال أربعتهم ثقات."],[572,"أم موسى عن علي حديثها مستقيم، فقال هي سرية لعلي٢ يخرج حديثها اعتبارا. وقلت له: حديث هشام بن زياد عن محمد بن كعب القرظي عن ابن عباس الحديث الطويل الذي فيه ذكر عمر بن عبد العزيز، فقل: أفسده عفان لأنه قال حدثنيه هشام قديما عن فلان عن محمد بن كعب ذكره اسمه الدارقطني فنسيته أنا، قال: فلما كان بعد، حدث به عن محمد بن كعب، قال أبو الحسن وبودي أن يكون صحيحا فإنه عندنا عالي، حدثنا به عبيد الله العيشي عن هشام قلت ابن منيع، قال: نعم. سمعته يقول:"],[573,"أبو يزيد الملائي عن ابن عمر مجهول."],[574,"أبو مريم الثقفي عن عمار مجهول متروك١."],[575,"وأبو سفيان ٢ عن أبي هريرة، هو مولى أبي أحمد بن جحش ثقة مديني."],[576,"وأبو مدرك متروك."],[577,"وأبو ثمامة الحناط ويقال القماح لا يعرف يترك."],[578,"وأبو سعيد بن عوذ عن مجاهد يحدث عنه أبو أحمد الزبيري لا يعرف اسمه٣ مكي يعتبر به، سمع من ابن الزبير النهدي عن الحسين بن علي، مجهول."],[579,"وقتادة عن أبي مراية بصري لم يحدث عنه غيره، يعتبر به."],[580,"وقتادة عن أبي ميمونة عن أبي هريرة مجهول يترك٤."],[581,"وأبو إسماعيل العبدي عن أنس متروك بصري."],[582,"وأبو رملة عن معاوية شامي مجهول يترك."],[583,"وأبو بكر بن أبي مريم قيل اسمه بكير حمصي متروك٥."],[584,"وأبو أمامة عن الأسود بن يزيد يحدث عنه محمد بن سوقة مجهول."],[585,"وأبو عبد الله عن يحي بن أبي كثير مجهول لا يعرف."],[586,"وأبو سعد الساعدي عن أنس مجهول يترك حديثه."],[587,"وأبو ماجد وقيل أبو ماجدة عن ابن مسعود مجهول متروك."],[588,"وأبو أحمد الزبيري عن أبي شعبة الطحان لا أعرف أبا شعبة مجهول."],[589,"أبو إسماعيل عن أبي حنظلة عن ابن عمر هو ابن أبي خالد، وأبو حنظلة لا يعرف اسمه ولا بأس به١."],[590,"المسعودي عن أبي عمرو وقيل أبي عمر دمشقي متروك."],[591,"وأبو زياد مولى آل دراج عن أبي بكر لا يعرف يترك."],[592,"وأبو عذبة٢ عن نافع مجهول، يروي حديث الغسل."],[593,"وأبو شعبة الطحان جار الأعمش لا يعرف اسمه كوفي، متروك."],[594,"وأبو عتبة الكندي عن أبي أمامة، حمصي يخرج حديثه اعتبارا لا يعرف اسمه."],[595,"ابن معانق أو أبو معانق عن أبي مالك الأشعري لا شيء مجهول."],[596,"وابن لاس الخزاعي مجهول لا يعرف ويقال أبو لاس."],[597,"وأبو عبد الرحمن المعافري مجهول."],[598,"وأبو حفصة مولى عائشة مجهول١ لا أعلم حدث به عنه غير يحي بن أبي كثير فيخرج حديث الكسوف، إذا حسن طريقه إلى يحي."],[599,"وأبو نصير الواسطي متروك لا أعرف اسمه يحدث عنه سويد بن عبد العزيز."],[600,"وأبو حريز مولى معاوية لا شيء مجهول وقيل أبو جرير."],[601,"أبو رافع الصائغ عن أبي هريرة، قيل اسمه نفيع٢ ولا يصح، هو بصري ثقة."],[602,"وسألته عن أبي الخطاب عن أبي سعيد الخدري فقال: مجهول."],[603,"وعن يعلى بن عطاء عن أبي علقمة عن أبي هريرة، فقال: أبو علقمة لا يعرف اسمه، ولا من هو ولكن يخرج هذا الحديث اعتبارا. حدث الأئمة عن يعلى."],[604,"وسمعته يقول: أبو مزاحم عن أبي هريرة لا يعرف يترك."],[605,"وأبو الربيع عن ابن عمر مجهول لا يحدث عنه إلا أبو سعيد الطحان٣."],[606,"وأبو بكر بن أبي موسى عن أبي موسى الأشعري، واسم أبي بكر هذا عمرو."],[607,"وأبو بكر بن أبي إياس، لا أعرفه."],[608,"وسمعته يقول: ابن عيينة أصله كوفي، أقام بمكة، وكان أبوه يحج به قديما. آخر السؤالات والحمد لله وحده وصلواته على سيدنا محمد وآله وصحبه وسلم، وحسبنا الله تعالى ونعم الوكيل."],[609,"أسئلة البرذعي لأبي زرعة الرازي. تحقيق د/ سعد هاشمي- ط المجلس العلمي- بالجامعة الإسلامية."],[610,"التاريخ لابن معين- رواية الدوري. تحقيق د/ أحمد محمد نور سيف- ط الأولى عام ١٣٩٩هـ."],[611,"تاريخ بغداد للخطيب البغدادي (ت ٤٦٣هـ) . ط الأولى عام ١٣٤٩هـ بمطبعة السعادة."],[612,"تاريخ التراث العربي- فؤاد سزكين. ترجمة د/ محمود فهمي حجازي، ود/ فهمي أبو الفضل. ط الثانية عام ١٩٧٧م- الهيئة المصرية العامة."],[613,"تاريخ جرجان- للحافظ السهمي (ت ٤٢٧هـ) . تصحيح المعلمي -ط بمطبعة مجلس دائرة المعارف العثمانية حيدر أباد١٣٥٠هـ."],[614,"التاريخ الكبير للإمام البخاري (ت٢٥٦هـ) . ط الأولى١٣٦١هـ بمطبعة دائرة المعارف العثمانية."],[615,"تحفة الأحوذي للمباركفوري. مراجعة عبد الوهاب عبد اللطيف، نشر محمد عبد المحسن الكتبي ط مطبعة المدني الطبعة الثانية."],[616,"تحفة الأشراف للحافظ جمال الدين المزي (ت٧٤٢هـ) . تصحيح وتعليق عبد الصمد شرف الدين. نشر الدار القيمة. ط الأولى."],[617,"التحفة اللطيفة للسخاوي (ت٩٠٢هـ) . تحقيق أسعد طرابزوني- ط مطبعة السنة المحمدية."],[618,"تذكرة الحفاظ للذهبي (ت٧٤٨هـ) . ط- مطبعة مجلس دائرة المعارف العثمانية. ط الثالثة عام ١٣٧٧هـ."],[619,"تقريب التهذيب للحافظ ابن حجر العسقلاني (ت٨٥٢هـ) . دار نشر الكتب الإسلامية –كوجر انوالة-باكستان- ط الأولى عام١٣٩٣هـ."],[620,"تهذيب التهذيب لابن حجر العسقلاني. ط بمطبعة دائرة المعارف النظامية. ط الأولى."],[621,"تهذيب الكمال للمزي. مخطوط مصور في مكتبة الجامعة الإسلامية."],[622,"الجرح والتعديل: لابن أبي حاتم (ت٣٢٧هـ) . تحقيق عبد الرحمن المعلمي- ط بمطبعة مجلس دائرة المعارف. ط الأولى عام ١٣٧١هـ."],[623,"الخلاصة لصفي الدين الخزرجي (ت٩٢٣هـ) . نشر مكتبة المطبوعات الإسلامية. حلب- ط الثانية عام١٣٩١هـ."],[624,"سنن ابن ماجه: للحافظ أبي عبد الله بن ماجه (ت٢٧٥هـ) . تحقيق محمد فؤاد عبد الباقي. ط دار احياء الكتب العربية عام١٣٧٢هـ."],[625,"سنن النسائي: بشرح السيوطي وحاشية السندي. ط دار إحياء التراث العربي. بيروت-لبنان."],[626,"سؤالات أبي عبيد الآجري. رسالة ماجستير. تحقيق محمد علي قاسم العمري. بإشراف د/ محمود أحمد ميرة."],[627,"سؤالات الحافظ السلفي لخميس الحوزي. تحقيق مطاع الطرابيشي. دمشق- مجمع اللغة العربية."],[628,"سؤالات الحاكم للدار قطني. نسخة مصورة في الجامعة الإسلامية تحت رقم (١٨١٨) مجموع."],[629,"سؤالات السلمي للدار قطني. نسخة مصورة في الجامعة الإسلامية تحت رقم (١٨١٨) مجموع."],[630,"الضعفاء والمتروكين للدار قطني. نسخة مصورة في الجامعة الإسلامية تحت رقم (١٨١٨) مجموع."],[631,"طبقات الفقهاد للشيرازي. تحقيق إحسان عباس. ط دائرة الرائد العربي. بيروت."],[632,"العلل ومعرفة الرجال: للإمام أحمد ابن حنبل (ت٢٤١هـ) . تحقيق د/ طلعت قوج، ود/ إسماعيل جراح. أنقرة١٩٦٣م."],[633,"الكاشف: للإمام الذهبي. تحقيق عزت علي عطية، وموسى محمد علي الموشى. ط الأولى ١٣٩٢هـ. ط دار النصر."],[634,"الكامل: لابن عدي. نسخة مصورة في مكتبة الدراسات العليا تحت رقم ١١٤/١١٥."],[635,"الكنى: لأبي أحمد الحاكم. نسخة مصورة في الجامعة الإسلامية. بدون رقم."],[636,"اللباب: لعز الدين ابن الأثير. ط دار صادر."],[637,"لسان الميزان: للحافظ ابن حجر العسقلاني (٨٥٢هـ) . نشر مؤسسة الأعلمي للمطبوعات."],[638,"مختصر سنن أبي داود: للمنذري. تحقيق أحمد محمد شاكر، ومحمد حامد الفقي. ط مطبعة السنة المحمدية."],[639,"المعجم المفهرس. النسخة المصورة من المكتبة الأزهرية- وهي في قسم المخطوطات تحت رقم (١٧١٩ مكبر) ."],[640,"المغني في ضبط أسماء الرجال: للفتى (ت٩٨٦هـ) . ط دار الكتاب العربي. بيروت، عام ١٣٩٩هـ."],[641,"ميزان الاعتدال: للإمام الذهبي (ت٩٤٨هـ) . تحقيق علي محمد البجاوي. ط دار إحياء الكتاب العربي."]]);
